#include "loommapper.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static lm_context_t context;
static lm_graph_t graph;
static lm_event_log_t events;
static void boot(void){platform_init();graph_init(&graph);event_log_init(&events);memset(&context,0,sizeof(context));context.state=LM_BASELINE;context.next_scan_ms=0;context.next_report_ms=0;context.battery_mv=driver_battery_mv();if(driver_init()!=LM_OK)context.state=LM_FAULT;}
static void publish(void){uint8_t frame[LM_PACKET_MAX];size_t length=protocol_encode_status(&context,&graph,frame,sizeof(frame));if(length>0u)platform_notify(frame,length);}
static void process_command(void){uint8_t frame[LM_PACKET_MAX];int count=platform_receive(frame,sizeof(frame));if(count<=0)return;lm_result_t r=protocol_handle(frame,(size_t)count,&context,&graph,&events);if(r!=LM_OK)context.fault_count++;}
static void scan_one(void){lm_channel_sample_t samples[LM_CHANNELS];if(driver_select_source(context.active_source)!=LM_OK||driver_capture(context.active_source,samples)!=LM_OK){context.fault_count++;context.state=LM_FAULT;return;}if(graph_update(&graph,context.active_source,samples,platform_millis(),&events)!=LM_OK){context.fault_count++;context.state=LM_FAULT;return;}context.active_source=(uint8_t)((context.active_source+1u)%LM_CHANNELS);if(context.active_source==0u){context.settled_scans++;if(context.state==LM_BASELINE&&context.settled_scans>=3u)context.state=LM_SCAN;}}
static void scheduler_step(void){uint32_t now=platform_millis();if(context.state!=LM_IDLE&&context.state!=LM_FAULT&&(int32_t)(now-context.next_scan_ms)>=0){scan_one();context.next_scan_ms=now+LM_SCAN_PERIOD_MS;}if((int32_t)(now-context.next_report_ms)>=0){context.battery_mv=driver_battery_mv();publish();context.next_report_ms=now+LM_REPORT_PERIOD_MS;}process_command();platform_set_led(context.state==LM_FAULT||context.battery_mv<LM_BATTERY_LOW_MV);platform_advance(5u);platform_sleep();}
static int check(bool condition,const char *name){if(!condition){fprintf(stderr,"FAIL: %s\n",name);return 1;}return 0;}
static int test_crc(void){static const uint8_t vector[]="123456789";int f=0;f+=check(lm_crc16(vector,9u)==0x29b1u,"crc16 vector");f+=check(lm_crc32(vector,9u)==0xcbf43926u,"crc32 vector");return f;}
static int test_classification(void){lm_channel_sample_t s={0};s.clip_present=true;s.noise_uv=200;s.baseline_uv=250;s.in_phase_uv=90000;int f=0;f+=check(classify_edge(&s,false)==LM_EDGE_GOOD,"good edge");s.in_phase_uv=700;f+=check(classify_edge(&s,false)==LM_EDGE_OPEN,"open edge");s.in_phase_uv=160000;f+=check(classify_edge(&s,true)==LM_EDGE_SHORT,"short edge");s.clip_present=false;f+=check(classify_edge(&s,false)==LM_EDGE_UNKNOWN,"missing clip");return f;}
static int test_event_log(void){lm_event_log_t log;event_log_init(&log);for(unsigned i=0;i<LM_EVENT_CAPACITY+5u;i++){lm_event_t e={i,1,2,LM_EDGE_GOOD,LM_EDGE_OPEN,(uint16_t)i};event_log_append(&log,&e);}lm_event_t latest;int f=0;f+=check(log.count==LM_EVENT_CAPACITY,"event ring capacity");f+=check(event_log_get(&log,0,&latest),"event newest exists");f+=check(latest.timestamp_ms==LM_EVENT_CAPACITY+4u,"event newest value");f+=check(!event_log_get(&log,LM_EVENT_CAPACITY,&latest),"event bounds");return f;}
static int test_graph(void){lm_graph_t g;lm_event_log_t log;lm_channel_sample_t samples[LM_CHANNELS];graph_init(&g);event_log_init(&log);for(uint8_t i=0;i<LM_CHANNELS;i++){samples[i].channel=i;samples[i].clip_present=true;samples[i].baseline_uv=200;samples[i].noise_uv=150;samples[i].in_phase_uv=i==3u?81000:500;samples[i].quadrature_uv=20;}int f=0;f+=check(graph_update(&g,0,samples,10,&log)==LM_OK,"graph update");f+=check(g.edge_count==LM_CHANNELS,"graph edge count");const lm_edge_t *edge=graph_find(&g,0,3);f+=check(edge!=NULL&&edge->kind==LM_EDGE_GOOD,"graph mapped edge");f+=check(g.graph_crc!=0u,"graph crc");return f;}
static size_t make_command(uint8_t type,const uint8_t *payload,uint16_t payload_len,uint8_t *out){out[0]=LM_MAGIC0;out[1]=LM_MAGIC1;out[2]=LM_PROTOCOL_VERSION;out[3]=type;out[4]=(uint8_t)payload_len;out[5]=(uint8_t)(payload_len>>8);if(payload_len>0u)memcpy(out+6,payload,payload_len);uint16_t crc=lm_crc16(out,6u+payload_len);out[6u+payload_len]=(uint8_t)crc;out[7u+payload_len]=(uint8_t)(crc>>8);out[8u+payload_len]='\n';return 9u+payload_len;}
static int test_protocol(void){lm_context_t ctx={0};lm_graph_t g;lm_event_log_t log;uint8_t packet[32];graph_init(&g);event_log_init(&log);size_t len=make_command(0x80u,NULL,0u,packet);int f=0;f+=check(protocol_handle(packet,len,&ctx,&g,&log)==LM_OK,"start command");f+=check(ctx.state==LM_BASELINE,"start state");packet[6]^=1u;f+=check(protocol_handle(packet,len,&ctx,&g,&log)==LM_ERR_CRC,"crc rejection");return f;}
static int test_integration(void){boot();for(unsigned i=0;i<900u;i++)scheduler_step();int f=0;f+=check(context.state==LM_SCAN,"baseline transition");f+=check(graph.edge_count==64u,"complete matrix");const lm_edge_t *e=graph_find(&graph,0,3);f+=check(e!=NULL&&e->kind==LM_EDGE_GOOD,"known harness path");f+=check(context.fault_count==0u,"no scheduler faults");return f;}
static int test_diagnostics(void){lm_calibration_block_t cal;lm_signal_stats_t signal;lm_signal_stats_t noise;lm_graph_summary_t summary;lm_calibration_defaults(&cal);lm_stats_init(&signal);lm_stats_init(&noise);for(int32_t i=0;i<16;i++){lm_stats_push(&signal,10000+i*20);lm_stats_push(&noise,100+i);}int f=0;f+=check(lm_calibration_valid(&cal),"calibration crc");f+=check(lm_calibration_set_gain(&cal,2u,1100u)==LM_OK,"calibration gain");f+=check(lm_calibration_apply(&cal,2u,1000)==1100,"calibration apply");f+=check(lm_stats_mean(&signal)>10000,"statistics mean");f+=check(lm_signal_quality(&signal,&noise)>500u,"signal quality");lm_graph_summarize(&graph,&summary);f+=check(summary.good>0u,"graph summary");f+=check(lm_graph_confidence(&graph)>0u,"graph confidence");f+=check(lm_battery_percent(3750u)==50u,"battery percent");return f;}
static int test_flex_watch(void){boot();for(unsigned i=0;i<900u;i++)scheduler_step();context.state=LM_FLEX_WATCH;driver_set_flex(true);for(unsigned i=0;i<900u;i++)scheduler_step();const lm_edge_t *edge=graph_find(&graph,4u,0u);int f=0;f+=check(edge!=NULL&&edge->kind==LM_EDGE_INTERMITTENT,"flex intermittent classification");f+=check(events.count>0u,"flex event recorded");f+=check(lm_event_severity_max(&events)>=600u,"flex event severity");return f;}
static int self_test(void){int failures=0;failures+=test_crc();failures+=test_classification();failures+=test_event_log();failures+=test_graph();failures+=test_protocol();failures+=test_integration();failures+=test_diagnostics();failures+=test_flex_watch();if(failures==0)printf("LoomMapper self-test: 8 suites passed\n");else fprintf(stderr,"LoomMapper self-test: %d checks failed\n",failures);return failures==0?EXIT_SUCCESS:EXIT_FAILURE;}
int main(int argc,char **argv){if(argc>1&&strcmp(argv[1],"--self-test")==0)return self_test();boot();for(unsigned i=0;i<1800u;i++){if(i==900u){context.state=LM_FLEX_WATCH;driver_set_flex(true);}scheduler_step();}printf("scan=%u edges=%u events=%u crc=%08x battery=%umV\n",graph.scan_sequence,graph.edge_count,events.count,graph.graph_crc,context.battery_mv);return context.state==LM_FAULT?EXIT_FAILURE:EXIT_SUCCESS;}
